<?php
$d = $dashboardSummary ?? [];
$money = static fn($v): string => number_format((float)$v, 0);
$currency = trim((string)($institute['currency_symbol'] ?? $institute['currency'] ?? 'PKR')) ?: 'PKR';
$fee = $d['fee'] ?? ['total'=>0,'paid'=>0,'remaining'=>0];
$feePercent = (float)$fee['total'] > 0 ? min(100, round(((float)$fee['paid'] / (float)$fee['total']) * 100)) : 0;
$attendanceTotal = (int)($d['present'] ?? 0) + (int)($d['absent'] ?? 0);
$attendancePercent = $attendanceTotal > 0 ? round(((int)$d['present'] / $attendanceTotal) * 100) : 0;
$staffPercent = (int)($d['employees'] ?? 0) > 0 ? round(((int)($d['staffPresent'] ?? 0) / (int)$d['employees']) * 100) : 0;
$esc = static fn($v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
?>
